import {buildDebtCapacity} from '../../../lib/credit-engine/debt-capacity/engine.ts';
import {id,stable,rank} from '../../../lib/credit-engine/debt-capacity/common.ts';
export const fingerprint=e=>id('capacity-golden',e);
const field=(r,k)=>k==='headroom'?r.headlineCapacity.monthlyIncrementalDebtServiceCapacity:k==='principal'?r.scenarioResults[0]?.prudentialPrincipalEquivalent:r;
export function compareCapacity(a,b,key='headroom',operator='EQ'){const x=field(a,key),y=field(b,key);return operator==='EQ'?stable(x)===stable(y):operator==='LT'?x<y:x>y;}
export function expectations(e,r,error=null){const out=[];const check=(ok,code,expected,actual,level='HARD')=>{if(!ok)out.push({code,expected,actual,level});};const ex=e.expected;
 if(ex.invalid){check(!!error&&error.includes(ex.invalid),'EXPECTED_REJECTION',ex.invalid,error);return out;}
 check(!!r&&!error,'EXECUTION',true,error);if(!r)return out;
 const h=r.headlineCapacity.monthlyIncrementalDebtServiceCapacity;
 const values={status:r.status,prudential:h.prudential,maximum:h.maximumPolicy,state:h.state,central:r.operatingBasis.centralOperatingBasis.value,conservative:r.operatingBasis.conservativeOperatingBasis.value,fullMonths:r.operatingBasis.fullMonthCount,observed:r.observedDebtServiceBasis.value,schedule:r.portfolioScheduledDebtService30d.value,nearAnchor:r.nearTerm30dView.existingDebtServiceAnchor.value,readiness:r.readinessReference.level,scenarioPrincipal:r.scenarioResults[0]?.prudentialPrincipalEquivalent,coverage:r.scenarioResults[0]?.requestedAmountCoverage,scenarioCount:r.scenarioResults.length};
 for(const[k,v]of Object.entries(values))if(Object.hasOwn(ex,k))check(v===ex[k],k.toUpperCase(),ex[k],v);
 for(const w of ex.warnings??[])check(r.warnings.includes(w),'MISSING_WARNING',w,r.warnings);
 for(const w of ex.scenarioWarnings??[])check(r.scenarioResults[0]?.warnings.includes(w),'SCENARIO_WARNING',w,r.scenarioResults[0]?.warnings);
 if(ex.discounted){const {payment,rate,months}=ex.discounted;let discounted=0;for(let n=1;n<=months;n++)discounted+=payment/(1+rate)**n;check(Math.abs(r.scenarioResults[0].prudentialPrincipalEquivalent-discounted)<.011,'DISCOUNTED_PAYMENT_SERIES',discounted,r.scenarioResults[0].prudentialPrincipalEquivalent);}
 if(ex.invariants){check(h.prudential===null||h.prudential>=0&&h.maximumPolicy>=h.prudential,'NONNEGATIVE_ORDER',true,h);check(r.indexReference.value===e.input.prescoreIndex.value,'INDEX_UNCHANGED',true,r.indexReference);check(r.readinessReference.level===e.input.financingReadiness.level,'READINESS_UNCHANGED',true,r.readinessReference);check(rank(r.confidence)<=rank(e.input.creditAssessment.confidence),'CONFIDENCE_NOT_PROMOTED',true,r.confidence);check(!r.comparable||r.status==='CALCULATED'&&e.input.creditAssessment.comparable,'COMPARABILITY',true,r.comparable);check((e.input.scenarios??[]).length===r.scenarioResults.length,'NO_IMPLICIT_SCENARIO',true,r.scenarioResults.length);for(const v of [r.recurringView,r.nearTerm30dView])if(v.incrementalHeadroom.prudential!==null)check(h.prudential<=v.incrementalHeadroom.prudential&&h.maximumPolicy<=v.incrementalHeadroom.maximumPolicy,'HEADLINE_NOT_OPTIMISTIC',true,h);}
 if(ex.defect){const fs=e.input.riskAssessment.findings,d=fs.find(f=>f.code==='RISK-BKI-CURRENT-OVERDUE');check(d?.severity==='MEDIUM'&&d.reasonCodes.includes('CURRENT_OVERDUE')&&!fs.some(f=>f.code==='RISK-BKI-HISTORICAL-DELINQUENCY'||f.reasonCodes.some(c=>/^DELINQUENCY_/.test(c))),'PERMANENT_DEFECT_CHAIN',true,fs.map(f=>f.reasonCodes));check(r.observedDebtServiceBasis.value===0,'NO_INVENTED_SERVICE_FROM_OVERDUE',0,r.observedDebtServiceBasis.value);}
 for(const a of ex.reviewAssertions??[])check(values[a.field]===a.value,'REVIEW_'+a.field,a.value,values[a.field],'REVIEW');return out;
}
export function runCapacityPack(pack){for(const e of pack.entries)if(pack.fingerprints[e.caseId]!==fingerprint(e))throw Error('CAPACITY_GOLDEN_FINGERPRINT_MISMATCH');const rs=pack.entries.map(e=>{const before=stable(e.input);let actual=null,error=null;try{actual=buildDebtCapacity(e.input);}catch(ex){error=ex.message;}const mismatches=expectations(e,actual,error);if(before!==stable(e.input))mismatches.push({code:'UPSTREAM_MUTATED',level:'HARD'});return {caseId:e.caseId,actual,error,mismatches};});for(const e of pack.entries){const r=rs.find(v=>v.caseId===e.caseId);for(const p of e.expected.relative??[]){const other=rs.find(v=>v.caseId===p.other);if(!r.actual||!other?.actual||!compareCapacity(r.actual,other.actual,p.field,p.operator))r.mismatches.push({code:'PAIRWISE_MISMATCH',level:'HARD',expected:p});}}return rs.map(r=>({...r,result:r.mismatches.some(m=>m.level==='HARD')?'FAIL':r.mismatches.length?'REVIEW':'PASS'}));}
